   | { kind: "else" }
   | { kind: "end" };

+function parseTag(expr: string, raw: boolean): Token {
+  const trimmed = expr.trim();
+  if (raw) return { kind: "value", expr: trimmed, raw: true };
+  if (trimmed === "else") return { kind: "else" };
+  if (trimmed === "/if") return { kind: "end" };
+  if (/^#if(\s|$)/.test(trimmed)) return { kind: "if", path: trimmed.slice(3).trim() };
+  return { kind: "value", expr: trimmed, raw: false };
+}
+
 /** Split a template into text and tag tokens. See README.md. */
 export function tokenize(template: string): Token[] {
-  throw new Error("not implemented");
+  const tokens: Token[] = [];
+  let i = 0;
+  while (i < template.length) {
+    const open = template.indexOf("{{", i);
+    if (open === -1) {
+      tokens.push({ kind: "text", text: template.slice(i) });
+      break;
+    }
+    if (open > i) tokens.push({ kind: "text", text: template.slice(i, open) });
+    const raw = template[open + 2] === "{";
+    const opener = raw ? 3 : 2;
+    const closer = raw ? "}}}" : "}}";
+    const close = template.indexOf(closer, open + opener);
+    if (close === -1) throw new Error("unterminated tag");
+    tokens.push(parseTag(template.slice(open + opener, close), raw));
+    i = close + closer.length;
+  }
+  return tokens;
 }
